  const rounds = readTournamentRounds(value.rounds, playerCount);
  if (!rounds) return null;
  const complete = rounds.every((round) =>
    round.matches.every(
      (match) => match.winnerSeed !== null && match.results[0] !== null && match.results[1] !== null,
    ),
