import { useLayoutEffect, useRef } from 'react';
import type { RefObject } from 'react';
import './tournament.css';

interface TournamentLeaveDialogProps {
  open: boolean;
  returnFocusRef: RefObject<HTMLButtonElement | null>;
  keepPlaying(): void;
  leave(): void;
}

export function TournamentLeaveDialog({
  open,
  returnFocusRef,
  keepPlaying,
  leave,
}: TournamentLeaveDialogProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const keepPlayingButton = useRef<HTMLButtonElement>(null);

  useLayoutEffect(() => {
    const element = dialog.current;
    if (!element) return;
    if (open && !element.open) {
      element.showModal();
      keepPlayingButton.current?.focus();
    } else if (!open && element.open) {
      element.close();
      returnFocusRef.current?.focus();
    }
  }, [open, returnFocusRef]);

  return (
    <dialog
      ref={dialog}
      className="tournament-leave-dialog"
      aria-labelledby="tournament-leave-heading"
      aria-describedby="tournament-leave-description"
      onCancel={(event) => {
        event.preventDefault();
        keepPlaying();
      }}
    >
      <h2 id="tournament-leave-heading">Leave tournament?</h2>
      <p id="tournament-leave-description">Your current tournament work will be lost.</p>
      <div className="tournament-leave-actions">
        <button ref={keepPlayingButton} type="button" className="control" onClick={keepPlaying}>
          Keep playing
        </button>
        <button type="button" className="control" onClick={leave}>
          Leave
        </button>
      </div>
    </dialog>
  );
}
import { expect, TestTimeouts, test } from './browser-test.ts';
import { generateBoard } from '../src/game/deck.ts';
import { isJsonObject } from '../src/game/saved-format.ts';
import type { Page } from '@playwright/test';

interface Pair {
  readonly first: number;
  readonly second: number;
}

function boardPairs(code: string): readonly Pair[] {
  const positions = new Map<number, number[]>();
  generateBoard(code).deck.forEach((face, index) => {
    const pair = positions.get(face) ?? [];
    pair.push(index);
    positions.set(face, pair);
  });
  return [...positions.values()].flatMap((indices) => {
    const first = indices[0];
    const second = indices[1];
    return first === undefined || second === undefined ? [] : [{ first, second }];
  });
}

async function playTurn(page: Page, code: string, finishesTournament = false): Promise<void> {
  await page.getByRole('button', { name: 'Start turn', exact: true }).click();
  const cards = page.locator('.board .card');
  await expect(cards).toHaveCount(generateBoard(code).deck.length);
  for (const pair of boardPairs(code)) {
    await cards.nth(pair.first).click();
    await cards.nth(pair.second).click();
  }
  if (finishesTournament) {
    await expect(page.locator('.tournament-champion')).toContainText('Champion:');
  } else {
    await expect(page.locator('.victory')).toContainText('Game complete in');
  }
}

async function matchCode(page: Page, roundIndex: number, matchIndex: number): Promise<string> {
  const code = await page
    .locator('.tournament-round')
    .nth(roundIndex)
    .locator('tbody tr')
    .nth(matchIndex)
    .locator('.tournament-code')
    .textContent();
  if (!code) throw new Error('Tournament bracket did not show a deal code.');
  return code.trim();
}

async function finalPlayerName(page: Page, cellIndex: number): Promise<string> {
  const text = await page
    .locator('.tournament-round')
    .nth(1)
    .locator('tbody tr')
    .nth(0)
    .locator('td')
    .nth(cellIndex)
    .textContent();
  if (!text) throw new Error('Tournament bracket did not show a finalist.');
  return text.split(' — ')[0]?.trim() ?? '';
}

