import { expect, TestTimeouts, test } from './browser-test.ts';
import { generateBoard } from '../src/game/deck.ts';
import { isJsonObject } from '../src/game/saved-format.ts';
import type { Page } from '@playwright/test';

interface Pair {
  readonly first: number;
  readonly second: number;
}

function boardPairs(code: string): readonly Pair[] {
  const positions = new Map<number, number[]>();
  generateBoard(code).deck.forEach((face, index) => {
    const pair = positions.get(face) ?? [];
    pair.push(index);
    positions.set(face, pair);
  });
  return [...positions.values()].flatMap((indices) => {
    const first = indices[0];
    const second = indices[1];
    return first === undefined || second === undefined ? [] : [{ first, second }];
  });
}

async function playTurn(page: Page, code: string, finishesTournament = false): Promise<void> {
